from taf.ul.trs_e2e_fw.lib.ems.netact.netact_base import NetactBase
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class CLS(NetactBase):
    def __init__(self):
        super(CLS, self).__init__()

    def delete_license(self, **kwargs):
        """
        Keyword deletes license directly from 'licenses' table. After deletion it is possible to add the same license
        to CLS. Port 3306 to cls-db node has to be opened beforehand.
        Please note that THIS IS NOT A SUPPORTED GUI OPERATION.

        Parameters:
        license_serialnumber: string, serial number of license e.g.: '0001034521025'
        license_filename : string, license file name e.g.: 'L2864799.XML'
        feature_code : string, license feature code e.g. '34065'
        db_username: string, if not passed, it will automatically provided
        db_password: string, if not passed, it will automatically provided
        alias: string, Netact instance name. Default value is 'default'.

        Note:
        For deleting license, user credentials should be root and db-host is required.
        Delete license will be a db-query.
        Either license_serialnumber, license_filename to be provided as argument or feature code.

        Returns: None

        Return Type: NA
        """

        feature_code = kwargs.get('feature_code')
        alias = kwargs.get('alias', 'default')
        if feature_code:
            filters = {'featureCode': str(feature_code)}
            license_output = self.netact_factory.netact.get_licenses(filters=filters, alias=alias)
            logger.info("feature info is :{}".format(license_output))
            if license_output:
                license_serialnumber = license_output[0][0]['serialNumber']
                license_filename = license_output[0][0]['fileName']
                logger.info("license_serialnumber is :{}, license_filename is :{}".format(license_serialnumber, license_filename))
                return self.netact_factory.netact.terminate_license(license_serialnumber=license_serialnumber,
                                                                    license_filename=license_filename, alias=alias)
            else:
                logger.error("No license exists with feature code : {}".format(feature_code))
        else:
            license_serialnumber = kwargs['license_serialnumber']
            license_filename = kwargs['license_filename']
            logger.info("license_serialnumber is :{}, license_filename is :{}".format(license_serialnumber, license_filename))
            return self.netact_factory.netact.terminate_license(license_serialnumber=license_serialnumber,
                                                                license_filename=license_filename, alias=alias)

    def upload_license(self, **kwargs):
        """
        Uploads license from given path or file-like object to CLS.

        Parameters:
        license: string, License content or path to license file, e.g.: '/tmp/O1400107.XML'
        license_name: string, If file is set as license its name will be used by default. Otherwise must be set
            explicitly, e.g.: 'O1400107.XML'.
        alias: string, Netact instance name. Default value is 'default'.

        Returns: license

        Return type: list(dict)
        """
        license = kwargs['license']
        license_name = kwargs['license_name']
        alias = kwargs.get('alias', 'default')
        return self.netact_factory.netact.upload_license(license=license, license_name=license_name, alias=alias)

    def get_licenses(self, **kwargs):
        """
        Gets licenses.

        Parameters:
        filters: dict(string,string), parameters for filtering licenses e.g. featureCode=5
            Available filters:
            "serialNumber", "fileName", "code", "name", "mode", "totalCapacity", "usedCapacity", "capacityUnit",
            "type", "startDate", "endDate", "targetType", "targetId", "featureCode", "featureName"
        require_unique: bool, if True, checks if only one element is found for given filters.
            In case there are multiple elements - raises ClsApiError
            Otherwise - returns the element
        alias: string, Name of execution context

        Returns: licenses, metadata

        Return Type: tuple(list(dict), dict)
        """
        require_unique = kwargs.get('require_unique', False)
        filters = kwargs.get('filters')
        alias = kwargs.get('alias', 'default')
        return self.netact_factory.netact.get_licenses(require_unique=require_unique, filters=filters, alias=alias)

    def get_features(self, **kwargs):
        """
        Gets features.

        Parameters:
        client_id: string, e.g. 'MRBTS-100728'
        filters: dict(string,string), parameters for filtering features e.g. featureCode=28444
            Available filters:
            'featureCode', 'capacity', 'type', 'allocations'
        require_unique: bool, if True, checks if only one element is found for given filters.
            In case there are multiple elements - raises ClsApiError
            Otherwise - returns the element
        alias: string, Name of execution context.

        Returns: features, metadata

        Return Type: tuple(list(dict), dict)
        """
        client_id = kwargs['client_id']
        require_unique = kwargs.get('require_unique', False)
        filters = kwargs.get('filters')
        alias = kwargs.get('alias', 'default')
        return self.netact_factory.netact.get_features(client_id=client_id, require_unique=require_unique,
                                                       filters=filters, alias=alias)

    def terminate_license(self, **kwargs):
        """
        Keyword terminates license the same way as CLS GUI. License will be permanently deleted, logs \
        will appear in GUI in 'Recent operations' tab. Terminated license can not be reused.

        feature_code : string, license feature code e.g. '34065'
        license_serialnumber: string, serial number of license e.g.: '0001034521025'
        license_filename: string, license file name e.g.: 'L2864799.XML'
        alias: string, Name of execution context.

        Either license_serialnumber, license_filename to be provided as argument or feature code.

        Returns: None

        Return Type: NA
        """
        feature_code = kwargs.get('feature_code')
        alias = kwargs.get('alias', 'default')
        if feature_code:
            filters = {'featureCode': str(feature_code)}
            license_output = self.netact_factory.netact.get_licenses(filters=filters, alias=alias)
            logger.info("feature info is :{}".format(license_output))
            if license_output:
                license_serialnumber = license_output[0][0]['serialNumber']
                license_filename = license_output[0][0]['fileName']
                logger.info("license_serialnumber is :{}, license_filename is :{}".format(license_serialnumber, license_filename))
                return self.netact_factory.netact.terminate_license(license_serialnumber=license_serialnumber,
                                                                    license_filename=license_filename, alias=alias)
            else:
                logger.error("No license exists with feature code : {}".format(feature_code))
        else:
            license_serialnumber = kwargs['license_serialnumber']
            license_filename = kwargs['license_filename']
            logger.info("license_serialnumber is :{}, license_filename is :{}".format(license_serialnumber, license_filename))
            return self.netact_factory.netact.terminate_license(license_serialnumber=license_serialnumber,
                                                                license_filename=license_filename, alias=alias)
